arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' -d '{"query":"{ __type(name: \"Query\") { fields(includeDeprecated: true) { name args { name type { kind name ofType { kind name ofType { kind name } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__type']['fields']:
    if f['name'] in ('cycles','cycle','users','issues','issueSearch','searchIssues'):
        print(f['name'])
        for a in f['args']:
            t=a['type']; tn=t['name'] or (t['ofType'] and (t['ofType']['name'] or (t['ofType'].get('ofType') or {}).get('name') or t['ofType']['kind']))
            print('  ', a['name'], tn)
"

